Method.Implementation:


  set checkGMRequest=##class(IHC.ITF.ITFCOMMON.DStruc.LdapCheckGMRequest).%New()
  set checkGMRequest.DN=mFilter 
  Set checkGMRequest.searchFilter = Searchbase
  //call ldap operation
  set tSC=process.SendRequestSync(LdapAddUpdateOperation,strRequest,.ldapResponse,900)
  if (('tSC)||ldapResponse.StringValue <=0)
  {
	  Set retVal = 0
  }



  set addGMRequest=##class(IHC.ITF.ITFCOMMON.DStruc.LdapAddUpdateRequest).%New()
  set addGMRequest.filter=mFilter 
  Set addGMRequest.baseDN = Searchbase
  Set addGMRequest.attrName = attrName
  Set addGMRequest.attrVal = attrVal
  Set addGMRequest.action = action
  //call ldap operation
  set tSC=process.SendRequestSync(LdapAddUpdateOperation,strRequest,.ldapResponse,900)
  if (('tSC))
  {
	  Set retVal = 0
  }

$$$TRACE("Inside  Method OnGetConnections")
Do ##super(.pArray,pItem)
Set pArray("Out-Ldap-Demogr-Ldap-AddUpdate")=""
Set pArray("Out-Ldap-Demogr-Ldap-Search")=""
